from solution import multiply
import pytest
from hypothesis import given
import hypothesis.strategies as st


# Reference model derived from spec + examples:
# unit digit is abs value mod 10 (example 14,-15 -> 4*5=20 proves abs for negatives)
def ref(a, b):
    return (abs(a) % 10) * (abs(b) % 10)


# ---- Explicit spec examples ----
def test_example_148_412():
    assert multiply(148, 412) == 16

def test_example_19_28():
    assert multiply(19, 28) == 72

def test_example_2020_1851():
    assert multiply(2020, 1851) == 0

def test_example_14_neg15():
    assert multiply(14, -15) == 20


# ---- Properties ----

@given(
    a=st.integers(min_value=-10**6, max_value=10**6),
    b=st.integers(min_value=-10**6, max_value=10**6),
)
def test_property_matches_reference_model(a, b):
    assert multiply(a, b) == ref(a, b)

@given(
    a=st.integers(min_value=-10**6, max_value=10**6),
    b=st.integers(min_value=-10**6, max_value=10**6),
)
def test_property_result_in_valid_digit_product_range(a, b):
    r = multiply(a, b)
    assert 0 <= r <= 81

@given(
    a=st.integers(min_value=-10**6, max_value=10**6),
    b=st.integers(min_value=-10**6, max_value=10**6),
)
def test_property_nonnegative(a, b):
    assert multiply(a, b) >= 0

@given(
    a=st.integers(min_value=-10**6, max_value=10**6),
    b=st.integers(min_value=-10**6, max_value=10**6),
)
def test_property_commutative(a, b):
    assert multiply(a, b) == multiply(b, a)

@given(
    a=st.integers(min_value=-10**6, max_value=10**6),
    b=st.integers(min_value=-10**6, max_value=10**6),
)
def test_property_sign_invariance(a, b):
    assert multiply(a, b) == multiply(abs(a), abs(b))
    assert multiply(a, b) == multiply(-abs(a), abs(b))
    assert multiply(a, b) == multiply(abs(a), -abs(b))
    assert multiply(a, b) == multiply(-abs(a), -abs(b))

@given(
    a=st.integers(min_value=-10**6, max_value=10**6),
    b=st.integers(min_value=-10**6, max_value=10**6),
)
def test_property_depends_only_on_unit_digits(a, b):
    assert multiply(a, b) == multiply(abs(a) % 10, abs(b) % 10)

@given(
    d1=st.integers(min_value=0, max_value=9),
    d2=st.integers(min_value=0, max_value=9),
    k1=st.integers(min_value=-1000, max_value=1000),
    k2=st.integers(min_value=-1000, max_value=1000),
)
def test_property_higher_digits_ignored(d1, d2, k1, k2):
    # Numbers sharing the same unit digit must give same result.
    # Construct numbers as k*10 +/- d to preserve unit digit abs-wise.
    a1 = k1 * 10 + d1
    a2 = k1 * 10 - d1 if d1 != 0 else a1
    b1 = k2 * 10 + d2
    # positive constructions share unit digits d1, d2
    assert multiply(a1, b1) == d1 * d2

@given(a=st.integers(min_value=-10**6, max_value=10**6))
def test_property_zero_unit_digit_gives_zero(a):
    # multiples of 10 have unit digit 0
    assert multiply(a, 0) == 0
    assert multiply(0, a) == 0
    assert multiply(a, 10) == 0
    assert multiply(a, -10) == 0
    assert multiply(a, 2020) == 0

@given(d=st.integers(min_value=0, max_value=9))
def test_property_single_digits_are_plain_product(d):
    for e in (0, 1, 5, 9):
        assert multiply(d, e) == d * e

def test_property_single_digit_full_table():
    for d1 in range(10):
        for d2 in range(10):
            assert multiply(d1, d2) == d1 * d2
            assert multiply(-d1, d2) == d1 * d2
            assert multiply(d1, -d2) == d1 * d2
            assert multiply(-d1, -d2) == d1 * d2

def test_property_boundary_values():
    assert multiply(0, 0) == 0
    assert multiply(0, 9) == 0
    assert multiply(10, 10) == 0
    assert multiply(-10, -10) == 0
    assert multiply(9, 9) == 81
    assert multiply(-9, -9) == 81
    assert multiply(-9, 9) == 81
    assert multiply(99, 99) == 81
    assert multiply(100, 1) == 0
    assert multiply(-1, -1) == 1
    assert multiply(-1, 1) == 1
    assert multiply(10**18, 10**18) == 0
    assert multiply(10**18 + 9, 10**18 + 9) == 81
    assert multiply(-10**18 - 3, 7) == 21

@given(n=st.integers(min_value=0, max_value=10**6))
def test_property_trailing_nines(n):
    a = n * 10 + 9
    b = n * 10 + 9
    assert multiply(a, b) == 81
    assert multiply(-a, -b) == 81
